def truncate_number(number: float) -> float:
    """Return the decimal fractional part of a positive floating point number."""
    return number - int(number)

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def string_transformation(A, B, rules):
    """
    Perform a string transformation from A to B using a list of transformation rules.
    The function performs a breadth‑first search up to a maximum of 10 steps and returns
    the minimum number of steps required to reach B from A, or "NO ANSWER!" if it is
    impossible to do so within 10 steps.
    """
    if A == B:
        return 0

    from collections import deque

    queue = deque()
    queue.append((A, 0))          # (current string, current depth)
    visited = {A}
    max_depth = 10

    while queue:
        current, depth = queue.popleft()

        if depth >= max_depth:
            continue

        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break

                new_string = current[:idx] + tgt + current[idx + len(src):]

                if new_string == B:
                    return depth + 1

                if new_string not in visited:
                    visited.add(new_string)
                    queue.append((new_string, depth + 1))

                # Move past this occurrence to find the next in the original string
                start = idx + 1

    return "NO ANSWER!"

def catalan_number(n: int) -> int:
    """Calculate the nth Catalan number using dynamic programming."""
    if n < 0:
        raise ValueError("n must be non-negative")
    catalan = [1]            # C(0) = 1
    for i in range(1, n + 1):
        total = 0
        for j in range(i):
            total += catalan[j] * catalan[i - 1 - j]
        catalan.append(total)
    return catalan[n]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Use a boolean DP array to track achievable sums up to V
    dp = [False] * (V + 1)
    dp[0] = True
    best = 0
    for i in range(n):
        vol = volumes[i]
        if vol > V:
            continue
        for j in range(V, vol - 1, -1):
            if dp[j - vol]:
                if not dp[j]:
                    dp[j] = True
                    if j > best:
                        best = j
    return V - best

def minimum_students_to_leave(heights):
    n = len(heights)
    if n <= 1:
        return 0
    # Longest increasing subsequence ending at each index
    inc = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1
    # Longest decreasing subsequence starting at each index
    dec = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1
    # Maximum length of a bitonic subsequence
    max_len = 0
    for i in range(n):
        bitonic_len = inc[i] + dec[i] - 1
        if bitonic_len > max_len:
            max_len = bitonic_len
    return n - max_len
